-- Queer Atlas: Asia hotel batch 1
-- Siem Reap, Shanghai, Hong Kong, New Delhi, Bali, Jakarta, Kyoto, Tokyo,
-- Kuala Lumpur, Manila, Seoul, Singapore, Phuket and Ho Chi Minh City.
-- Three researched LGBTQ+-focused or LGBTQ+-welcoming hotels per destination.
-- Editorial and source check: 2026-08-23.
--
-- No ratings or review totals are manufactured. Inclusion is based on either
-- a first-party LGBTQ+ statement/operation or a current specialist LGBTQ+
-- travel listing. Coordinates identify the hotel property, never a city centre.
-- Safe to run repeatedly; existing rows are matched by city + hotel name.

begin;

alter table if exists public.places
  add column if not exists venue_intel jsonb not null default '{}'::jsonb;

with raw_hotels as (
  select * from jsonb_to_recordset($hotels$
[
 {"name":"MEN's Resort & Spa","city":"siem_reap","description":"An explicitly gay, male-only boutique resort in Siem Reap with ten rooms, saltwater pool, gym and included access to its men's sauna and spa. This is a genuine queer specialist stay rather than a general hotel inferred to be friendly.","vibe":"intimate gay men's resort with pool and sauna social life","tags_csv":"men_only,relax,social","hours":"Hotel accommodation with sauna and spa facilities; confirm reception, check-in and current facility hours directly.","link":"https://www.mens-resort.com/","location":"Wat Bo Street, Wat Polanka area, Siem Reap 171201, Cambodia","lat":13.3627557,"lng":103.8659704,"arrival":"Small-resort arrival is best coordinated in advance, especially for airport transfers or late check-in.","best":"Gay men wanting a self-contained queer stay with pool, gym and sauna access close to central Siem Reap.","audience":"Male-only hotel guests and gay men using the associated wellness facilities; check current visitor rules.","dress":"Resort casual; pool, sauna and spa areas have their own practical clothing and conduct rules.","inclusion":"The property describes itself as a gay hotel and operates specifically for men.","basis":"First-party gay hotel positioning plus current Travel Gay gay-owned/gay-managed listing.","class":"Gay men's boutique resort and spa","coord":"OpenStreetMap hotel-property point checked against the published Wat Bo/Wat Polanka address.","sources":["https://www.mens-resort.com/","https://www.travelgay.com/gay-siem-reap-hotels"]},
 {"name":"Rambutan Hotel & Resort Siem Reap","city":"siem_reap","description":"A gay-owned and gay-managed pair of boutique properties around saltwater pools near Wat Damnak and the Old Market. Rambutan combines a strongly queer guest mix with a broader welcoming social-enterprise model.","vibe":"gay-owned Khmer-style oasis near the Old Market","tags_csv":"social,relax,mixed","hours":"Hotel reception and accommodation operate daily; confirm restaurant, massage, pool and airport-transfer schedules directly.","link":"https://rambutansiemreap.com/","location":"Rambutan Lane, Phum Wat Damnak, Kum Sala Komreuk, Krom 10, Siem Reap 17259, Cambodia","lat":13.35137939,"lng":103.85488892,"arrival":"The hotel sits in a pedestrian lane; share transfer and luggage plans before arrival.","best":"Queer travellers wanting a gay-owned central base with Old Market access and a relaxed pool environment.","audience":"A high proportion of gay guests alongside LGBTQ+ friends, couples and other respectful adult travellers.","dress":"Relaxed tropical clothing works; pool and restaurant spaces use ordinary resort etiquette.","inclusion":"Travel Gay identifies Rambutan as gay-owned and managed, and the current booking record confirms the live property.","basis":"Current specialist gay-owned listing plus official property and booking records.","class":"Gay-owned boutique hotel and resort","coord":"Current booking-engine GeoCoordinates checked against the official Rambutan Lane address.","sources":["https://rambutansiemreap.com/contact-us/","https://www.travelgay.com/gay-siem-reap-hotels"]},
 {"name":"Hotel Be Angkor","city":"siem_reap","description":"A tiny art-led hotel on The Passage beside Siem Reap's Old Market. Current LGBTQ+ specialist coverage identifies it as gay-friendly, making it a compact alternative to the city's larger pool resorts.","vibe":"artistic micro-hotel in the middle of Old Market life","tags_csv":"cozy,cultural,mixed","hours":"Small hotel accommodation; confirm live reception, check-in and luggage arrangements before arrival.","link":"https://www.travelgay.com/siem-reap-gay-guesthouses","location":"The Passage, Old Market Area, Siem Reap 171000, Cambodia","lat":13.3543032,"lng":103.854615,"arrival":"With only a few rooms, arrival instructions and late check-in should be confirmed directly.","best":"Travellers prioritising the Old Market, walkability and local art over full resort facilities.","audience":"LGBTQ+ couples, solo visitors and general culture-led guests in a very small mixed hotel.","dress":"No hotel dress code; everyday tropical city clothing is appropriate.","inclusion":"Current Travel Gay coverage describes Hotel Be Angkor as gay-friendly.","basis":"Current LGBTQ+ specialist guesthouse listing and verified live property location.","class":"Small art boutique hotel","coord":"OpenStreetMap hotel-property point checked against The Passage location.","sources":["https://www.travelgay.com/siem-reap-gay-guesthouses","https://www.travelgay.com/gay-siem-reap-hotels"]},

 {"name":"The Langham Shanghai Xintiandi","city":"shanghai","description":"A five-star hotel beside Xintiandi with spa, pool and high-service dining. Travel Gay currently includes it among Shanghai's LGBTQ+-welcoming luxury hotels, with strong access to the former French Concession.","vibe":"refined Xintiandi luxury with polished city energy","tags_csv":"luxury,relax,mixed","hours":"Hotel reception operates 24 hours; spa, pool, restaurants and bars use current schedules.","link":"https://www.langhamhotels.com/en/the-langham/shanghai/","location":"99 Madang Road, Huangpu District, Shanghai 200021, China","lat":31.2237257,"lng":121.4698926,"arrival":"Concierge-led arrival; reserve spa and destination dining separately, especially on holidays.","best":"Xintiandi, central sightseeing and discreet access toward Shanghai's changing queer social scene.","audience":"International couples, business travellers, luxury guests and LGBTQ+ visitors in a mixed hotel.","dress":"Smart-casual suits dining and bars; spa and pool areas have practical rules.","inclusion":"Current Travel Gay luxury coverage documents the property as welcoming to LGBTQ+ travellers.","basis":"Current Travel Gay Shanghai luxury listing plus official hotel information.","class":"5-star luxury hotel","coord":"OpenStreetMap hotel-building point checked against the official 99 Madang Road address.","sources":["https://www.travelgay.com/gay-shanghai-luxury-hotels","https://www.langhamhotels.com/en/the-langham/shanghai/discover/our-location/"]},
 {"name":"Park Hyatt Shanghai","city":"shanghai","description":"A high-rise luxury hotel inside the Shanghai World Financial Center in Lujiazui, with skyline rooms, pool and spa. Travel Gay currently includes it as an LGBTQ+-welcoming Shanghai luxury choice.","vibe":"serene sky-high luxury above Pudong's financial district","tags_csv":"luxury,relax,mixed","hours":"Hotel reception operates 24 hours; pool, spa, restaurants and lounges follow current schedules.","link":"https://www.hyatt.com/park-hyatt/en-US/shaph-park-hyatt-shanghai","location":"100 Century Avenue, Pudong New Area, Shanghai 200120, China","lat":31.2365768,"lng":121.5030406,"arrival":"The hotel occupies upper floors of a major tower; follow its dedicated arrival and lift directions.","best":"Skyline views, Lujiazui business and a quiet luxury retreat rather than immediate nightlife frontage.","audience":"LGBTQ+ couples, international business guests and luxury travellers in a broad mixed environment.","dress":"Smart-casual is suitable for lounges and restaurants; wellness spaces have separate rules.","inclusion":"Current LGBTQ+ specialist travel coverage lists the hotel as a welcoming luxury option.","basis":"Current Travel Gay Shanghai luxury listing plus official Hyatt property information.","class":"5-star high-rise luxury hotel","coord":"Shanghai World Financial Center building coordinate checked against the official 100 Century Avenue address.","sources":["https://www.travelgay.com/gay-shanghai-luxury-hotels","https://www.hyatt.com/park-hyatt/en-US/shaph-park-hyatt-shanghai"]},
 {"name":"Hotel Indigo Shanghai on the Bund","city":"shanghai","description":"A design-focused hotel on the south Bund with river views, rooftop dining and a contemporary local-art identity. It appears in Travel Gay's current Shanghai hotel selection for LGBTQ+ travellers.","vibe":"colourful Bund design stay with rooftop river views","tags_csv":"luxury,cultural,mixed","hours":"Hotel reception operates 24 hours; rooftop, restaurants, pool and gym follow current schedules.","link":"https://www.ihg.com/hotelindigo/hotels/us/en/shanghai/shgnb/hoteldetail","location":"585 Zhongshan East 2nd Road, Huangpu District, Shanghai 200010, China","lat":31.2281122,"lng":121.4956739,"arrival":"Bund traffic can slow vehicle arrival; rooftop dining should be reserved separately.","best":"Design travellers wanting Bund views and central cultural access with a quieter hotel base.","audience":"Couples, business visitors, design travellers and LGBTQ+ guests in a mixed boutique setting.","dress":"Creative city clothing works; rooftop dining is generally smart-casual.","inclusion":"Current Travel Gay coverage includes the property among Shanghai's welcoming hotel choices.","basis":"Current specialist LGBTQ+ travel listing plus official IHG information.","class":"Upscale design boutique hotel","coord":"OpenStreetMap hotel-building point checked against the official 585 Zhongshan South Road address.","sources":["https://www.travelgay.com/gay-shanghai-luxury-hotels","https://www.ihg.com/hotelindigo/hotels/us/en/shanghai/shgnb/hoteldetail"]},

 {"name":"Eaton HK","city":"hong_kong","description":"A culture-led Jordan hotel whose programming and public identity actively engage LGBTQ+ art, community and counterculture. The Terrible Baby venue, food hall and community spaces make this more than a generic friendly stay.","vibe":"queer-positive cultural hub with energetic Kowloon social spaces","tags_csv":"cultural,social,mixed","hours":"Hotel reception operates 24 hours; music, culture, dining, pool and event programmes use separate schedules.","link":"https://www.eatonworkshop.com/en-us/hong-kong/","location":"380 Nathan Road, Jordan, Kowloon, Hong Kong","lat":22.3080618,"lng":114.1718264,"arrival":"Public events can make the ground floors busy; hotel check-in remains separate from programme access.","best":"Queer culture, local food and Jordan access in a socially engaged hotel environment.","audience":"LGBTQ+ creatives, couples, artists, local event audiences and general international guests.","dress":"Expressive city style is welcome; programmed events publish any specific access rules.","inclusion":"Eaton's own cultural platform regularly centres LGBTQ+ creators and community programming.","basis":"First-party queer cultural programming plus current specialist LGBTQ+ hotel coverage.","class":"Culture-led lifestyle hotel","coord":"OpenStreetMap hotel-building point checked against the official 380 Nathan Road address.","sources":["https://www.eatonworkshop.com/en-us/hong-kong/","https://www.travelgay.com/gay-hong-kong-hotels"]},
