 {"name":"Hotel ICON","city":"hong_kong","description":"An independent teaching and design hotel in Tsim Sha Tsui East with harbour views, pool and strong hospitality facilities. Travel Gay currently marks it Approved for LGBTQ+ customers.","vibe":"independent harbour-view design with serious service polish","tags_csv":"luxury,cultural,mixed","hours":"Hotel reception operates 24 hours; pool, spa, restaurants and shuttle services follow current schedules.","link":"https://www.hotel-icon.com/","location":"17 Science Museum Road, Tsim Sha Tsui East, Kowloon, Hong Kong","lat":22.3008025,"lng":114.1796535,"arrival":"Normal full-service arrival; reserve harbour-view dining and spa treatments separately.","best":"Tsim Sha Tsui culture and harbour access in a distinctive independent property.","audience":"Couples, design travellers, business guests and LGBTQ+ visitors in a mixed upscale crowd.","dress":"Smart-casual suits restaurants; pool and spa have practical rules.","inclusion":"The current Travel Gay Approved record documents LGBTQ+ acceptance and welcoming service.","basis":"Current Travel Gay Approved listing plus official Hotel ICON information.","class":"5-star independent design hotel","coord":"OpenStreetMap hotel-building point checked against the official 17 Science Museum Road address.","sources":["https://www.travelgay.com/gay-hong-kong-hotels","https://www.hotel-icon.com/about-icon"]},

 {"name":"The LaLiT New Delhi","city":"new_delhi","description":"A central luxury hotel whose Kitty Su nightclub has a documented history of hosting and supporting Delhi's LGBTQ+ community. The hotel's own inclusion work gives it a stronger basis than directory proximity alone.","vibe":"central luxury with a concrete queer nightlife and advocacy link","tags_csv":"luxury,social,cultural","hours":"Hotel reception operates 24 hours; Kitty Su, spa, pool, restaurants and events use separate live schedules.","link":"https://www.thelalit.com/the-lalit-delhi/","location":"Barakhamba Avenue, Connaught Place, New Delhi 110001, India","lat":28.6314643,"lng":77.2271911,"arrival":"Hotel and nightclub entry are separate; confirm Kitty Su's current event, ID and door policy before travelling.","best":"Queer travellers wanting a central full-service hotel with a real link to Delhi's LGBTQ+ event history.","audience":"LGBTQ+ guests, business travellers, couples and a broad international luxury audience.","dress":"Hotel areas are smart-casual; Kitty Su events may publish a nightlife dress and ID policy.","inclusion":"The LaLiT and Kitty Su have publicly supported LGBTQ+ events, performers and employment inclusion.","basis":"First-party LGBTQ+ nightlife/community work plus current Travel Gay hotel coverage.","class":"5-star luxury hotel with nightclub","coord":"OpenStreetMap hotel-property point checked against the official Barakhamba Avenue address.","sources":["https://www.thelalit.com/the-lalit-delhi/location/","https://www.travelgay.com/new-delhi-hotels"]},
 {"name":"The Lodhi","city":"new_delhi","description":"A high-service luxury hotel on Lodhi Road with large rooms, spa, pool and destination dining. Travel Gay currently marks it Approved as a welcoming option for LGBTQ+ New Delhi travellers.","vibe":"quiet architectural luxury with strong wellness focus","tags_csv":"luxury,relax,mixed","hours":"Hotel reception operates 24 hours; spa, pool, restaurants and club facilities use current schedules.","link":"https://www.thelodhi.com/","location":"Lodhi Road, New Delhi 110003, India","lat":28.5915262,"lng":77.238125,"arrival":"Concierge-led arrival; reserve spa and dining separately and communicate accessibility needs early.","best":"A private, wellness-led luxury stay with central heritage access rather than nightlife at the door.","audience":"LGBTQ+ couples, international leisure travellers and business guests in a mixed luxury environment.","dress":"Smart-casual suits restaurants and public areas; wellness facilities use practical attire rules.","inclusion":"Travel Gay's current Approved programme documents LGBTQ+ acceptance and a welcoming service standard.","basis":"Current Travel Gay Approved listing plus official Lodhi information.","class":"5-star luxury hotel","coord":"OpenStreetMap hotel-property point checked against the official Lodhi Road address.","sources":["https://www.travelgay.com/new-delhi-hotels","https://www.thelodhi.com/contact-us/"]},
 {"name":"The Oberoi New Delhi","city":"new_delhi","description":"A landmark luxury hotel beside Delhi Golf Club and Humayun's Tomb, with spa, pool and multiple restaurants. Its current Travel Gay Approved listing supplies the LGBTQ+-welcoming evidence.","vibe":"landmark Delhi luxury with calm, formal service","tags_csv":"luxury,relax,mixed","hours":"Hotel reception operates 24 hours; restaurants, spa and pool follow current schedules.","link":"https://www.oberoihotels.com/hotels-in-delhi/","location":"Dr Zakir Hussain Marg, New Delhi 110003, India","lat":28.5965326,"lng":77.239815,"arrival":"High-service hotel arrival; restaurant and wellness reservations should be made separately.","best":"Heritage sightseeing, quiet luxury and high-touch service away from denser nightlife areas.","audience":"LGBTQ+ couples, diplomats, business guests and international luxury travellers in a mixed hotel.","dress":"Smart-casual to formal clothing suits dining and lounges; pool and spa have separate rules.","inclusion":"Current Travel Gay Approved status documents acceptance of LGBTQ+ guests.","basis":"Current Travel Gay Approved listing plus official Oberoi property information.","class":"5-star luxury hotel","coord":"OpenStreetMap hotel-building point checked against the official Dr Zakir Hussain Marg address.","sources":["https://www.travelgay.com/new-delhi-hotels","https://www.oberoihotels.com/hotels-in-delhi/contact-us/"]},

